import type { EngineInterface, Register } from 'claude-code'

import { denyMessage, destructive, isSecretPath, mayBeSecret, SECRET, touchesSecret } from './lib'
import type { Verdict } from './lib'

type $ = EngineInterface

// Estado do mod: quantos bloqueios nesta sessão e se o usuário liberou o turno.
let blocked = 0
let isReleased = false

/** Recusa a chamada: o modelo lê a mensagem, a pessoa vê o toast e o contador. */
function deny($: $, verdict: Verdict) {
  blocked += 1
  $.ui.toast(`🛡️ Guardião bloqueou: ${verdict.motivo}`)
  $.ui.status(`🛡️ ${blocked} ${blocked === 1 ? 'bloqueio' : 'bloqueios'}`)

  return { deny: denyMessage(verdict) }
}

export const register: Register = (on, options) => {
  const allowForcePush = options.permitirForcePush === true

  // A válvula de escape: só a pessoa, digitando, libera o turno.
  on('prompt.submit', async ($, e, next) => {
    if (e.origin.kind === 'composer') isReleased = /\blibera-guardiao\b/.test(e.text)

    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    if (e.agentId === undefined) isReleased = false

    return next(e)
  })

  // Ferramentas de arquivo: o caminho vem pronto em file_path.
  on('tool.call', { tool: /^(Read|Edit|Write)$/ }, async ($, e, next) => {
    const path = 'file_path' in e ? String(e.file_path) : ''
    if (isReleased || !isSecretPath(path)) return next(e)

    return deny($, SECRET)
  })

  // Grep lê conteúdo também: vale o segredo no path ou no glob (`.env*`).
  on('tool.call', { tool: 'Grep' }, async ($, e, next) => {
    const { path, glob } = e as { path?: unknown; glob?: unknown }
    const targets = [path, glob].filter((value): value is string => typeof value === 'string')
    if (isReleased || !targets.some(mayBeSecret)) return next(e)

    return deny($, SECRET)
  })

  // Bash: segredos lidos por cat/grep/source... e comandos que destroem.
  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    if (isReleased) return next(e)
    if (touchesSecret(e.command)) return deny($, SECRET)
    const verdict = destructive(e.command, allowForcePush)

    return verdict === undefined ? next(e) : deny($, verdict)
  })
}

