// Lógica pura do guardiao: decide se um caminho é segredo e se um comando é destrutivo.

/** Por que bloqueou e o que o agente deve fazer no lugar. */
export type Verdict = { motivo: string; alternativa: string }

/**
 * Arquivos de segredo: .env (menos os modelos .env.example/.sample/.template),
 * chaves privadas, .npmrc e credenciais de nuvem. Chave pública (.pub) passa.
 */
export function isSecretPath(path: string): boolean {
  const clean = path.replace(/^['"]|['"]$/g, '')
  if (clean.endsWith('.pub')) return false

  return [
    /(^|\/)\.env(\.(?!(example|sample|template)$)[\w.-]+)?$/,
    /\.(pem|key)$/,
    /(^|\/)id_(rsa|ed25519|ecdsa|dsa)[\w.-]*$/,
    /(^|\/)\.npmrc$/,
    /(^|\/)credentials[\w.-]*\.json$/,
    /(^|\/)\.aws\/credentials$/,
  ].some(pattern => pattern.test(clean))
}

export const SECRET: Verdict = {
  motivo: 'arquivo de segredo',
  alternativa:
    'Não leia nem altere arquivos de segredo. Se precisar saber quais variáveis existem, use o .env.example; se precisar de um valor, peça ao usuário.',
}

// Nomes de segredo contra os quais um glob é testado: `.en[v]` ou `*.pem` casam com algum.
const SECRET_SAMPLES = ['.env', '.env.local', '.env.production', 'server.pem', 'tls.key', 'id_rsa', 'id_ed25519', '.npmrc', 'credentials.json']

/** `a{b,c}d` vira `abd` e `acd` (sem aninhar), como o shell expande. */
function expandBraces(word: string): string[] {
  const match = /\{([^{}]*,[^{}]*)\}/.exec(word)
  if (match === null) return [word]
  const head = word.slice(0, match.index)
  const tail = word.slice(match.index + match[0].length)

  return (match[1] ?? '').split(',').flatMap(choice => expandBraces(`${head}${choice}${tail}`))
}

function globToRegExp(glob: string): RegExp {
  const source = glob.replace(/\[!?([^\]]*)\]|[*?]|[.+^${}()|\\]/g, (token, cls?: string) => {
    if (cls !== undefined) return `[${token[1] === '!' ? '^' : ''}${cls.replace(/\\/g, '\\\\')}]`
    if (token === '*') return '[^/]*'
    if (token === '?') return '[^/]'
    return `\\${token}`
  })

  return new RegExp(`^${source}$`)
}

/**
 * Um glob pode cair num segredo? Primeiro o próprio glob preenchido (`.env.dev*`
 * vira `.env.dev` e `.env.devx`), depois os nomes de segredo contra o glob. Um
 * `*` sozinho (`src/*`) não casa com eles, para não barrar o uso comum; um que
 * comece com ponto (`.*`) casa, porque pega o .env.
 */
function globMaySecret(path: string): boolean {
  const classes = path.replace(/\[(!?)([^\]]*)\]/g, (_, negated: string, cls: string) => (negated === '' && cls !== '' ? cls[0]! : 'x'))
  if (['', 'x'].some(fill => isSecretPath(classes.replace(/\?/g, 'x').replace(/\*/g, fill)))) return true
  const name = path.split('/').pop() ?? ''
  const literal = name.replace(/\[[^\]]*\]|[*?]/g, '')
  if (literal.length < 2 && !name.startsWith('.')) return false
  const pattern = globToRegExp(name)
  if (/(^|\/)\.aws\/[^/]*$/.test(path) && pattern.test('credentials')) return true

  return SECRET_SAMPLES.some(sample => pattern.test(sample) && isSecretPath(sample))
}

/**
 * Uma palavra, já como o shell a entrega, aponta para um segredo? Expande chaves
 * e trata glob; em `if=.env` ou `--file=.env` vale o valor.
 */
export function mayBeSecret(word: string): boolean {
  const values = [word, ...(/^[\w-]*=(.+)$/.exec(word)?.slice(1) ?? [])]

  return values.flatMap(expandBraces).some(path => {
    const name = path.split('/').pop() ?? ''
    // Nome com espaço é prosa (`-m "não versionar o .env"`); espaço só na pasta não conta.
    if (/\s/.test(name)) return false

    return /[*?[]/.test(name) ? globMaySecret(path) : isSecretPath(path)
  })
}

// Programas que só citam o nome de um arquivo, sem ler o conteúdo.
const NAMERS = new Set(['echo', 'printf', 'ls', 'test', '[', 'touch', 'mkdir', 'cd', 'rm', 'which', 'type'])

// Prefixos que rodam o comando seguinte: `env git reset --hard` é `git reset --hard`.
const WRAPPERS = new Set(['env', 'command', 'builtin', 'exec', 'nice', 'nohup', 'time', 'sudo', 'doas', 'timeout', 'stdbuf', 'ionice', 'xargs'])
const WRAPPER_VALUE_OPTIONS = new Set(['-u', '-g', '-n', '-k', '-s', '-C', '-c', '-p', '-o', '-e', '-i', '-I', '-L', '-P'])
const SHELLS = new Set(['sh', 'bash', 'zsh', 'dash', 'ksh'])

/** O nome do programa, sem caminho (`/bin/rm`). */
export const programOf = (word: string | undefined) => (word ?? '').split('/').pop() ?? ''

/** Tira atribuições (`FOO=1`) e prefixos como env, sudo e timeout da frente do comando. */
function unwrap(words: string[]): string[] {
  let rest = words
  for (;;) {
    const start = rest.findIndex(word => !/^[A-Za-z_]\w*=/.test(word))
    rest = start < 0 ? [] : rest.slice(start)
    if (!WRAPPERS.has(programOf(rest[0]))) return rest
    rest = rest.slice(1)
    while (rest[0] !== undefined && (rest[0].startsWith('-') || /^\d+(\.\d+)?[smhd]?$/.test(rest[0]))) {
      rest = rest.slice(WRAPPER_VALUE_OPTIONS.has(rest[0]) ? 2 : 1)
    }
  }
}

/** Lê `$(...)` a partir do `(`: o conteúdo e onde ele fecha. */
function readSubstitution(text: string, open: number): { body: string; end: number } {
  let depth = 0
  for (let i = open; i < text.length; i += 1) {
    if (text[i] === '(') depth += 1
    else if (text[i] === ')' && --depth === 0) return { body: text.slice(open + 1, i), end: i }
  }

  return { body: text.slice(open + 1), end: text.length }
}

/** Os `$(...)` e crases de um texto em que só eles valem, como o corpo de um heredoc. */
function substitutionsIn(text: string): string[] {
  const found: string[] = []
  for (let i = 0; i < text.length; i += 1) {
    if (text[i] === '\\') {
      i += 1
    } else if (text[i] === '$' && text[i + 1] === '(') {
      const substitution = readSubstitution(text, i + 1)
      found.push(substitution.body)
      i = substitution.end
    } else if (text[i] === '`') {
      const end = text.indexOf('`', i + 1)
      found.push(text.slice(i + 1, end < 0 ? text.length : end))
      i = end < 0 ? text.length : end
    }
  }

  return found
}

/**
 * Tira o corpo dos heredocs, que o programa lê pela entrada e não são nomes de
 * arquivo. Num delimitador sem aspas (`<<EOF`) o shell ainda roda os `$(...)` do
 * corpo; com aspas (`<<'EOF'`), o corpo é texto puro.
 */
function splitHeredocs(command: string): { text: string; inner: string[] } {
  const inner: string[] = []
  const text = command.replace(
    /(<<-?\s*(['"]?)(\w+)\2[^\n]*)\n([\s\S]*?)\n\s*\3\s*(?=\n|$)/g,
    (_, head: string, quote: string, __: string, body: string) => {
      if (quote === '') inner.push(...substitutionsIn(body))
      return head
    },
  )

  return { text, inner }
}

type Parsed = { segments: string[][]; redirects: string[]; inner: string[] }

/**
 * Lê o comando como o shell: as palavras saem sem as aspas e barras que o shell
 * tira (`"git" reset '--hard'` é `git reset --hard`); `;`, `&`, `|`, quebra de
 * linha e parênteses separam trechos fora de aspas. O alvo de `<` e `>` vai para
 * `redirects` (o de `<<` não é arquivo); os `$(...)` e crases que o shell roda,
 * fora de aspas simples, vão para `inner`.
 */
export function parse(command: string): Parsed {
  const { text, inner } = splitHeredocs(command)
  const parsed: Parsed = { segments: [], redirects: [], inner }
  let words: string[] = []
  let word = ''
  let isWord = false
  let quote = ''
  let redirect: 'file' | 'other' | null = null

  const endWord = () => {
    if (isWord) {
      if (redirect === 'file') parsed.redirects.push(word)
      else if (redirect === null) words.push(word)
      redirect = null
    }
    word = ''
    isWord = false
  }
  const endSegment = () => {
    endWord()
    const rest = unwrap(words)
    if (rest.length > 0) parsed.segments.push(rest)
    words = []
    redirect = null
  }

  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i] ?? ''
    if (quote === "'") {
      if (ch === "'") quote = ''
      else word += ch
    } else if (ch === '$' && text[i + 1] === '(') {
      const substitution = readSubstitution(text, i + 1)
      parsed.inner.push(substitution.body)
      word += '$()'
      isWord = true
      i = substitution.end
    } else if (ch === '`') {
      const end = text.indexOf('`', i + 1)
      parsed.inner.push(text.slice(i + 1, end < 0 ? text.length : end))
      word += '``'
      isWord = true
      i = end < 0 ? text.length : end
    } else if (quote === '"') {
      if (ch === '"') quote = ''
      else if (ch === '\\' && /[$`"\\\n]/.test(text[i + 1] ?? '')) word += text[++i]
      else word += ch
    } else if (ch === "'" || ch === '"') {
      quote = ch
      isWord = true
    } else if (ch === '\\') {
      word += text[++i] ?? ''
      isWord = true
    } else if (/[;&|\n()]/.test(ch)) {
      endSegment()
    } else if (/\s/.test(ch)) {
      endWord()
    } else if (ch === '<' || ch === '>') {
      endWord()
      let op = ch
      while (/[<>&]/.test(text[i + 1] ?? '')) op += text[++i]
      redirect = op.startsWith('<<') ? 'other' : 'file'
    } else {
      word += ch
      isWord = true
    }
  }
  endSegment()

  return parsed
}

/** O que um trecho manda outro shell rodar: `bash -c '...'` e `eval ...`. */
function nestedCommand(words: readonly string[]): string[] {
  const head = programOf(words[0])
  if (head === 'eval') return [words.slice(1).join(' ')]
  if (!SHELLS.has(head)) return []
  const flag = words.findIndex((word, i) => i > 0 && /^-\w*c\w*$/.test(word))
  const script = flag < 0 ? undefined : words[flag + 1]

  return script === undefined ? [] : [script]
}

/** O comando lido e, recursivamente, o que ele manda rodar: `$(...)`, crases, `bash -c`, `eval`. */
export function commandsIn(command: string, depth = 0): Parsed[] {
  const parsed = parse(command)
  if (depth >= 8) return [parsed]
  const nested = [...parsed.inner, ...parsed.segments.flatMap(nestedCommand)].filter(text => text.trim() !== '')

  return [parsed, ...nested.flatMap(text => commandsIn(text, depth + 1))]
}

/** Os trechos do comando, cada um em palavras, já sem prefixos como env e sudo. */
export const segments = (command: string) => commandsIn(command).flatMap(parsed => parsed.segments)

/** O comando Bash lê, copia ou redireciona um arquivo de segredo? */
export function touchesSecret(command: string): boolean {
  return commandsIn(command).some(parsed => {
    // Redirecionamentos (`< .env`, `> .env`, `>> .env`) valem para qualquer programa.
    if (parsed.redirects.some(mayBeSecret)) return true

    return parsed.segments.some(words => {
      const head = programOf(words[0])
      if (NAMERS.has(head)) return false
      // Em cp/mv o último argumento é o destino: `cp .env.example .env` cria, não vaza.
      const args = head === 'cp' || head === 'mv' ? words.slice(1, -1) : words.slice(1)

      return args.some(mayBeSecret)
    })
  })
}

const DANGEROUS_TARGETS = new Set(['/', '/*', '~', '~/', '~/*', '$HOME', '${HOME}', '$HOME/', '*', '.', './', '..', '../', '.*'])

/** Opções curtas juntas (`-rf`) viram letras; as longas ficam como estão. */
function hasFlag(args: readonly string[], short: string, long: string): boolean {
  return args.some(arg => arg === long || (/^-[a-zA-Z]+$/.test(arg) && arg.includes(short)))
}

/** O subcomando do git e o que vem depois, pulando `-C dir` e `-c chave=valor`. */
function gitArgs(words: readonly string[]): string[] {
  const rest = words.slice(1)
  while (rest[0]?.startsWith('-')) rest.splice(0, rest[0] === '-C' || rest[0] === '-c' ? 2 : 1)

  return rest
}

/** O comando Bash é destrutivo? Devolve o motivo, ou undefined se pode rodar. */
export function destructive(command: string, allowForcePush: boolean): Verdict | undefined {
  if (/\bDROP\s+(TABLE|DATABASE|SCHEMA)\b/i.test(command) && /\b(psql|mysql|mariadb|sqlite3|sqlcmd|duckdb|mongosh)\b/.test(command)) {
    return { motivo: 'DROP em banco de dados', alternativa: 'Apagar tabela ou banco é decisão do usuário: mostre o comando e peça para ele rodar.' }
  }

  for (const words of segments(command)) {
    const head = programOf(words[0])
    const args = words.slice(1)

    const isRecursive = hasFlag(args, 'r', '--recursive') || hasFlag(args, 'R', '--recursive')
    if (head === 'rm' && isRecursive && args.some(arg => DANGEROUS_TARGETS.has(arg))) {
      return { motivo: 'rm recursivo na raiz, no home ou no projeto inteiro', alternativa: 'Apague só os caminhos específicos que precisam sair (ex.: rm -rf node_modules dist).' }
    }
    if (head === 'chmod' && hasFlag(args, 'R', '--recursive') && args.some(arg => arg === '777' || arg === 'a+rwx')) {
      return { motivo: 'chmod -R 777', alternativa: 'Dê só a permissão necessária ao arquivo específico (ex.: chmod +x script.sh).' }
    }
    if (head !== 'git') continue

    const [sub, ...rest] = gitArgs(words)
    if (sub === 'push' && !allowForcePush && hasFlag(rest, 'f', '--force')) {
      return { motivo: 'git push --force', alternativa: 'Use git push --force-with-lease, que não apaga commits que outra pessoa enviou.' }
    }
    if (sub === 'reset' && rest.includes('--hard')) {
      return { motivo: 'git reset --hard', alternativa: 'Isso descarta mudanças sem volta. Use git stash para guardá-las, ou pergunte ao usuário.' }
    }
    if (sub === 'clean' && hasFlag(rest, 'f', '--force')) {
      return { motivo: 'git clean -f', alternativa: 'Rode git clean -n para listar o que sairia e mostre ao usuário antes de apagar.' }
    }
  }

  return undefined
}

/** A mensagem que o modelo lê no lugar do resultado da ferramenta. */
export function denyMessage(verdict: Verdict): string {
  return `🛡️ Guardião: bloqueado (${verdict.motivo}). ${verdict.alternativa} Se o usuário quiser liberar, ele escreve libera-guardiao no próximo prompt.`
}

