{
  "name": "guardiao",
  "version": "0.1.0",
  "description": "Veta ações perigosas do agente: ler arquivos de segredo (.env, chaves), rm -rf na raiz, push --force, reset --hard, DROP TABLE",
  "author": {
    "name": "Junior Martins"
  },
  "userConfig": {
    "permitirForcePush": {
      "type": "boolean",
      "title": "Permitir git push --force",
      "description": "Desligado, o agente só pode usar --force-with-lease",
      "default": false
    }
  }
}
